{{--
  responsive() auto: the same measuring as @acunsoft/datatable-dom's
  autoResponsive(), as an Alpine x-init. Columns are hidden (lowest priority
  first, then from the right; never priority 1) only while the table does
  not fit, and come back when there is room; nothing is hidden once the user
  sized columns (adt-user-widths). Printed inside an attribute,
  so the script uses single quotes only.
--}}
(() => { const root = $el; let observer; const apply = () => { observer?.disconnect(); const table = root.querySelector('table.adt-table'); const head = table?.tHead?.rows[table.tHead.rows.length - 1]; const scroller = table?.parentElement; if (table && head && scroller) { const cells = [...head.cells]; const idOf = cell => cell.dataset.columnId ?? (cell.classList.contains('adt-actions') ? '__actions' : undefined); const level = cell => Number((/adt-col--p(\d)/.exec(cell.className) || [])[1] ?? 1); const candidates = cells.map((cell, index) => ({ cell, index, level: level(cell) })).filter(item => item.level > 1 && idOf(item.cell) !== undefined).sort((a, b) => b.level - a.level || b.index - a.index); const rows = [...table.rows].filter(row => row.cells.length === cells.length); const setHidden = hidden => { for (const row of rows) [...row.cells].forEach((cell, index) => cell.classList.toggle('adt-auto-hidden', hidden.has(index))); const ids = new Set([...hidden].map(index => idOf(cells[index]))); table.querySelectorAll('.adt-detail-item[data-column-id]').forEach(item => item.classList.toggle('adt-auto-shown', ids.has(item.dataset.columnId))); table.classList.toggle('adt-auto-collapsed', hidden.size > 0); }; const hidden = new Set(); setHidden(hidden); for (const candidate of table.classList.contains('adt-user-widths') ? [] : candidates) { if (table.scrollWidth <= scroller.clientWidth + 1) break; hidden.add(candidate.index); setHidden(hidden); } } observer.observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] }); }; let queued = false; const schedule = () => { if (queued) return; queued = true; queueMicrotask(() => { queued = false; apply(); }); }; observer = new MutationObserver(schedule); apply(); if (window.ResizeObserver) new ResizeObserver(schedule).observe(root); })()